package org.dextur.reputation.storage;

import java.nio.file.*;
import java.util.*;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.investigation.InvestigationData.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.*;
import org.junit.jupiter.params.provider.*;
import org.testcontainers.containers.*;
import static org.junit.jupiter.api.Assertions.*;

@Tag("database") abstract class InvestigationDatabaseContract {
    @org.junit.jupiter.api.io.TempDir Path directory;
    abstract JdbcDatabaseContainer<?> container();
    Settings.Database configuration(){var c=container();return new Settings.Database(c.getHost(),c.getMappedPort(3306),c.getDatabaseName(),c.getUsername(),"DEXTURREPUTATION_DB_PASSWORD","disable",4,2000,60000);}
    Map<String,String> environment(){return Map.of("DEXTURREPUTATION_DB_PASSWORD",container().getPassword());}
    SqlStorage open()throws Exception{return SqlStorage.mysql(configuration(),environment(),false);}
    @BeforeEach void reset()throws Exception{try(var b=open()){InvestigationContract.configure(b,directory);try(var c=b.connect();var s=c.createStatement()){var tables=new ArrayList<>(SqlProtection.TABLES);tables.addAll(List.of("dr_investigation","dr_administration","dr_recovery","dr_tiers","dr_active_votes","dr_votes","dr_profiles","dr_player_preferences","dr_storage_control"));for(var table:tables)s.executeUpdate("DELETE FROM "+table);}}}
    @ParameterizedTest @EnumSource(InvestigationContract.Scenario.class)void equivalentContracts(InvestigationContract.Scenario scenario)throws Exception{try(var b=open()){InvestigationContract.run(scenario,b,directory);}}
    @Test void restartAndV7()throws Exception{StorageSnapshot before;try(var b=open()){InvestigationContract.run(InvestigationContract.Scenario.RESTORE,b,directory);before=b.snapshot();}try(var b=open()){assertEquals(before,b.snapshot());try(var c=b.connect();var s=c.createStatement();var rows=s.executeQuery("SELECT MAX(version) FROM dr_schema_history")){rows.next();assertEquals(7,rows.getInt(1));}}}
    @Test void rollbackCorruptionAndRepair()throws Exception{try(var b=open()){InvestigationContract.configure(b,directory);var vote=InvestigationContract.cast(b,InvestigationContract.VOTER,org.dextur.reputation.api.VoteType.POSITIVE,InvestigationContract.NOW);var before=b.snapshot();try(var c=b.connect();var s=c.createStatement()){s.execute("ALTER TABLE dr_investigation ADD CONSTRAINT phase7_failure CHECK(kind<>'AUDIT')");try{assertThrows(Exception.class,()->b.moderate(InvestigationContract.request(Action.INVALIDATE,vote.operationId())));assertEquals(before,b.snapshot());}finally{s.execute("ALTER TABLE dr_investigation DROP "+(container() instanceof MySQLContainer?"CHECK":"CONSTRAINT")+" phase7_failure");}s.executeUpdate("UPDATE dr_profiles SET community_score=99,visible_score=99 WHERE player_uuid='"+InvestigationContract.TARGET+"'");b.moderate(InvestigationContract.request(Action.RECALCULATE_REPUTATION,InvestigationContract.TARGET));assertEquals(0,b.getOrCreate(InvestigationContract.TARGET,"global").visibleScore());b.moderate(InvestigationContract.request(Action.INVALIDATE,vote.operationId()));s.executeUpdate("UPDATE dr_investigation SET revision=revision+1");}}assertThrows(Exception.class,this::open);try(var b=database();var c=b.dataSource().getConnection();var s=c.createStatement()){s.executeUpdate("UPDATE dr_investigation SET revision=revision-1");}}
    @Test void batchFailureRollsBackCursorAndResumesExactlyOnce()throws Exception{Files.writeString(directory.resolve("administration.yml"),new String(Objects.requireNonNull(getClass().getResourceAsStream("/administration.yml")).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).replace("batch-size: 10","batch-size: 1"));try(var b=open()){InvestigationContract.configure(b,directory);InvestigationContract.cast(b,InvestigationContract.VOTER,org.dextur.reputation.api.VoteType.POSITIVE,InvestigationContract.NOW);InvestigationContract.cast(b,UUID.randomUUID(),org.dextur.reputation.api.VoteType.POSITIVE,InvestigationContract.NOW);var plan=b.plan(Action.INVALIDATE,"global",new Filter(null,InvestigationContract.TARGET,null,"",null,null,"","",null),"CONSOLE","Batch retry",InvestigationContract.NOW);UUID operation=UUID.randomUUID();b.begin(operation,plan,InvestigationContract.NOW);assertEquals("1",b.advance(operation,"CONSOLE",false,InvestigationContract.NOW).operation().values().get("cursor"));try(var c=b.connect();var query=c.createStatement()){String blocked=UUID.nameUUIDFromBytes((operation+"/1").getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();query.execute("ALTER TABLE dr_investigation ADD CONSTRAINT phase7_batch_failure CHECK(kind<>'AUDIT' OR record_id<>'"+blocked+"')");try{assertThrows(Exception.class,()->b.advance(operation,"CONSOLE",false,InvestigationContract.NOW));assertEquals("PAUSED",b.snapshot().investigation().get(Kind.BULK,operation).status());assertEquals("1",b.snapshot().investigation().get(Kind.BULK,operation).values().get("cursor"));assertEquals(350000,b.snapshot().protection().scores().getFirst().currentUnits());}finally{query.execute("ALTER TABLE dr_investigation DROP "+(container() instanceof MySQLContainer?"CHECK":"CONSTRAINT")+" phase7_batch_failure");}}assertEquals("COMPLETED",b.advance(operation,"CONSOLE",false,InvestigationContract.NOW).operation().status());assertTrue(b.advance(operation,"CONSOLE",false,InvestigationContract.NOW).mutations().isEmpty());}}
    Database database()throws Exception{var db=new Database();db.open(configuration(),environment());return db;}
    @Test void fullPortableMigrationAllSixDirections()throws Exception{for(var from:StorageType.values())for(var to:StorageType.values())if(from!=to){reset();Path work=directory.resolve(from+"-"+to);StorageFixtures.resources(work);Files.writeString(work.resolve("storage.yml"),config(from));Files.writeString(work.resolve("target.yml"),config(to));StorageSnapshot before;try(var b=StorageManager.create(work,Settings.load(work),environment(),false)){RecoveryFixtures.complete(b,work);b.features(PolicyConfiguration.load(work));b.investigation(AdministrationConfiguration.load(work));var pending=b.snapshot().protection().assessments().stream().filter(a->a.status()==org.dextur.reputation.domain.protection.ProtectionData.Status.PENDING).findFirst().orElseThrow();b.moderate(InvestigationContract.request(Action.REJECT,pending.voteId()));b.moderate(InvestigationContract.request(Action.RESTORE,pending.voteId()));var flag=b.snapshot().investigation().records().stream().filter(record->record.kind()==Kind.FLAG).findFirst().orElseThrow();b.moderate(new Request(UUID.randomUUID(),"global",Action.RESOLVE_FLAG,flag.id(),"CONSOLE","Migration resolution",flag.revision(),"FALSE_POSITIVE",RecoveryFixtures.NOW.plusSeconds(100)));b.administer(PolicyContract.override(RecoveryFixtures.PLAYER,"chat.send",org.dextur.reputation.domain.policy.AdministrationData.Override.FORCE_DENY,RecoveryFixtures.NOW.plusSeconds(100)));var filter=new Filter(null,pending.target(),null,"",null,null,"","",null);var plan=b.plan(Action.INVALIDATE,"global",filter,"CONSOLE","Migration metadata",RecoveryFixtures.NOW.plusSeconds(100));b.begin(UUID.randomUUID(),plan,RecoveryFixtures.NOW.plusSeconds(100));before=b.snapshot();}new StorageMigration().migrate(work,work.resolve("target.yml"),work.resolve("backups"),environment());try(var b=StorageManager.create(work,Settings.load(work),environment(),false)){assertEquals(before,b.snapshot());assertFalse(b.snapshot().investigation().records().isEmpty());}}}
    String config(StorageType type)throws Exception{var d=configuration();return StorageFixtures.config(type).replace("host: localhost","host: "+d.host()).replace("port: 3306","port: "+d.port()).replace("database: dexturreputation","database: "+d.schema()).replace("username: dexturreputation","username: "+d.username()).replace("ssl-mode: verify-full","ssl-mode: disable");}
}
